SELECT DISTINCT s.session_uuid FROM workspace.session_registrations r JOIN sessions.sessions s ON s.id = r.session_id JOIN sessions.session_goals sg ON sg.session_id = s.id WHERE r.project_id = 993478 AND lower(sg.display_name) = lower('observer-1') AND r.released_at IS NULL AND r.lease_expires_at > now() AND s.session_uuid <> '9bf31507-d53e-4711-9813-8087f3416a27'
